SELECT FROM files f LEFT JOIN `user` u ON u.id = f.user_id WHERE f.visibility = 'PUBLIC' AND f.status = 'PUBLISHED' AND f.node_type = 'FILE'
AND f.title LIKE CONCAT('%', #{query.keyword}, '%')
AND f.category = #{query.category}
AND (f.category IS NULL OR f.category = '')
ORDER BY f.created_at DESC, f.id DESC LIMIT #{offset}, #{limit}

SELECT id, title, original_name, file_size, created_at, updated_at
FROM files
WHERE user_id = #{userId}
  AND node_type = 'FILE'
ORDER BY updated_at DESC, id DESC
LIMIT #{offset}, #{limit}

